import type { Context } from "hono"
import type { ContentfulStatusCode } from "hono/utils/http-status"

import consola from "consola"

export class HTTPError extends Error {
  response: Response

  constructor(message: string, response: Response) {
    super(message)
    this.response = response
  }
}

export function badRequest(message: string): HTTPError {
  return new HTTPError(
    message,
    Response.json(
      { error: { type: "invalid_request_error", message } },
      { status: 400 },
    ),
  )
}

interface ErrorEnvelope {
  error: {
    message: string
    type?: string
    code?: string | null
    param?: string | null
  }
  [key: string]: unknown
}

interface AnthropicErrorEnvelope {
  type: "error"
  error: { type: string; message: string }
  request_id?: string
}

interface NormalizedHTTPError {
  status: ContentfulStatusCode
  body: unknown
  structured: ErrorEnvelope | AnthropicErrorEnvelope | undefined
  requestId: string | undefined
}

const SAFE_ERROR_HEADERS = [
  "x-copilot-service-request-id",
  "x-github-request-id",
  "x-request-id",
  "retry-after",
  "x-ratelimit-limit",
  "x-ratelimit-remaining",
  "x-ratelimit-reset",
] as const

const LOCAL_ERROR_MESSAGE = "An unexpected error occurred."
const ABORT_ERROR_MESSAGE = "Client closed request."

function isErrorEnvelope(value: unknown): value is ErrorEnvelope {
  if (!value || typeof value !== "object") return false
  const nested = (value as { error?: unknown }).error
  if (!nested || typeof nested !== "object") return false
  return typeof (nested as { message?: unknown }).message === "string"
}

function isAnthropicEnvelope(value: unknown): value is AnthropicErrorEnvelope {
  if (!value || typeof value !== "object") return false
  const record = value as { type?: unknown; error?: unknown }
  if (
    record.type !== "error"
    || !record.error
    || typeof record.error !== "object"
  ) {
    return false
  }
  const nested = record.error as { type?: unknown; message?: unknown }
  return typeof nested.type === "string" && typeof nested.message === "string"
}

function typeForStatus(status: number): string {
  if (status === 400) return "invalid_request_error"
  if (status === 401) return "authentication_error"
  if (status === 403) return "permission_error"
  if (status === 404) return "not_found_error"
  if (status === 409) return "conflict_error"
  if (status === 429) return "rate_limit_error"
  return "api_error"
}

function messageForStatus(status: number): string {
  if (status === 400) return "Invalid request."
  if (status === 401) return "Authentication failed."
  if (status === 403) return "Permission denied."
  if (status === 404) return "Resource not found."
  if (status === 409) return "Request conflict."
  if (status === 429) return "Rate limit exceeded."
  return "An unexpected upstream error occurred."
}

function copySafeHeaders(c: Context, response: Response): void {
  for (const name of SAFE_ERROR_HEADERS) {
    const value = response.headers.get(name)
    if (value) c.header(name, value)
  }
}

function responseRequestId(response: Response): string | undefined {
  return (
    response.headers.get("x-copilot-service-request-id")
    ?? response.headers.get("x-github-request-id")
    ?? response.headers.get("x-request-id")
    ?? undefined
  )
}

async function normalizeHTTPError(
  c: Context,
  error: HTTPError,
): Promise<NormalizedHTTPError> {
  const response = error.response
  copySafeHeaders(c, response)
  let parsed: unknown
  try {
    parsed = JSON.parse(await response.clone().text())
  } catch {
    parsed = undefined
  }
  const structured =
    isAnthropicEnvelope(parsed) || isErrorEnvelope(parsed) ? parsed : undefined
  return {
    status: response.status as ContentfulStatusCode,
    body: structured,
    structured,
    requestId:
      (isAnthropicEnvelope(structured) ? structured.request_id : undefined)
      ?? responseRequestId(response),
  }
}

function isAbortError(error: unknown): boolean {
  return error instanceof Error && error.name === "AbortError"
}

function logUnexpected(error: unknown): void {
  const kind = error instanceof Error ? error.name : typeof error
  consola.error(`Unexpected non-stream error (${kind})`)
}

function logHTTPFailure(
  status: number,
  requestId: string | undefined,
  structured: ErrorEnvelope | AnthropicErrorEnvelope | undefined,
): void {
  const type =
    isAnthropicEnvelope(structured) ?
      structured.error.type
    : (structured?.error.type ?? structured?.error.code)
  consola.error(
    `Upstream non-stream error (status=${status}${type ? `, type=${type}` : ""}${requestId ? `, request_id=${requestId}` : ""})`,
  )
}

export async function forwardError(c: Context, error: unknown) {
  if (error instanceof HTTPError) {
    const normalized = await normalizeHTTPError(c, error)
    logHTTPFailure(
      normalized.status,
      normalized.requestId,
      normalized.structured,
    )
    if (isErrorEnvelope(normalized.structured)) {
      return c.json(normalized.structured, normalized.status)
    }
    if (isAnthropicEnvelope(normalized.structured)) {
      return c.json(
        {
          error: {
            type: normalized.structured.error.type,
            code: null,
            message: normalized.structured.error.message,
            param: null,
          },
        },
        normalized.status,
      )
    }
    return c.json(
      {
        error: {
          type: "upstream_error",
          code: "upstream_error",
          message: messageForStatus(normalized.status),
          param: null,
        },
      },
      normalized.status,
    )
  }

  if (isAbortError(error)) {
    consola.debug("Non-stream request aborted by client")
    return c.json(
      {
        error: {
          type: "request_aborted",
          code: "request_aborted",
          message: ABORT_ERROR_MESSAGE,
          param: null,
        },
      },
      499 as ContentfulStatusCode,
    )
  }

  logUnexpected(error)
  return c.json(
    {
      error: {
        type: "server_error",
        code: "internal_error",
        message: LOCAL_ERROR_MESSAGE,
        param: null,
      },
    },
    500,
  )
}

export async function forwardAnthropicError(c: Context, error: unknown) {
  if (error instanceof HTTPError) {
    const normalized = await normalizeHTTPError(c, error)
    logHTTPFailure(
      normalized.status,
      normalized.requestId,
      normalized.structured,
    )
    if (isAnthropicEnvelope(normalized.structured)) {
      return c.json(normalized.structured, normalized.status)
    }
    if (isErrorEnvelope(normalized.structured)) {
      return c.json(
        {
          type: "error" as const,
          error: {
            type:
              normalized.structured.error.type
              ?? typeForStatus(normalized.status),
            message: normalized.structured.error.message,
          },
        },
        normalized.status,
      )
    }
    return c.json(
      {
        type: "error" as const,
        error: {
          type: typeForStatus(normalized.status),
          message: messageForStatus(normalized.status),
        },
      },
      normalized.status,
    )
  }

  if (isAbortError(error)) {
    consola.debug("Anthropic non-stream request aborted by client")
    return c.json(
      {
        type: "error" as const,
        error: { type: "api_error", message: ABORT_ERROR_MESSAGE },
      },
      499 as ContentfulStatusCode,
    )
  }

  logUnexpected(error)
  return c.json(
    {
      type: "error" as const,
      error: { type: "api_error", message: LOCAL_ERROR_MESSAGE },
    },
    500,
  )
}

/**
 * Error envelope coverage for /v1/messages.
 *
 * The route speaks the Anthropic contract, whose errors carry a top-level
 * `type: "error"` alongside the nested error object. Before this was fixed the
 * endpoint returned the correct shape only when it was passing an upstream
 * rejection through, and an OpenAI-shaped one whenever the proxy raised the
 * error itself.
 *
 * The upstream envelopes asserted here were captured live from
 * api.githubcopilot.com: /v1/messages returns a top-level type and a
 * request_id, while /chat/completions returns {"error":{"message","code"}} with
 * no top-level type. They are genuinely different contracts, which is why
 * /chat/completions keeps forwardError.
 */
import { afterEach, beforeEach, describe, expect, it, mock } from "bun:test"

import type { ModelsResponse } from "~/services/copilot/get-models"

import { state } from "~/lib/state"
import { server } from "~/server"

const originalFetch = globalThis.fetch
const originalModels = state.models
const originalToken = state.copilotToken

const catalog = {
  object: "list",
  data: [
    {
      id: "claude-sonnet-5",
      name: "claude-sonnet-5",
      object: "model",
      vendor: "anthropic",
      version: "1",
      preview: false,
      model_picker_enabled: true,
      supported_endpoints: ["/v1/messages"],
      capabilities: {
        family: "claude-sonnet-5",
        limits: { max_output_tokens: 64000 },
        object: "model_capabilities",
        supports: { tool_calls: true },
        tokenizer: "o200k_base",
        type: "chat",
      },
    },
    {
      id: "gpt-5.5",
      name: "gpt-5.5",
      object: "model",
      vendor: "openai",
      version: "1",
      preview: false,
      model_picker_enabled: true,
      supported_endpoints: ["/responses"],
      capabilities: {
        family: "gpt-5.5",
        limits: { max_output_tokens: 64000 },
        object: "model_capabilities",
        supports: { tool_calls: true },
        tokenizer: "o200k_base",
        type: "chat",
      },
    },
  ],
} as unknown as ModelsResponse

function mockFetchReturning(response: () => Response) {
  globalThis.fetch = mock(() =>
    Promise.resolve(response()),
  ) as unknown as typeof fetch
}

function post(body: string) {
  return server.request("/v1/messages", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body,
  })
}

function validBody(model = "claude-sonnet-5") {
  return JSON.stringify({
    model,
    max_tokens: 64,
    messages: [{ role: "user", content: "hi" }],
  })
}

beforeEach(() => {
  state.copilotToken = "test-token"
  state.models = catalog
})

afterEach(() => {
  globalThis.fetch = originalFetch
  state.models = originalModels
  state.copilotToken = originalToken
})

describe("/v1/messages error envelope", () => {
  it("forwards an upstream Anthropic envelope unchanged, keeping request_id", async () => {
    mockFetchReturning(
      () =>
        new Response(
          JSON.stringify({
            type: "error",
            error: {
              type: "invalid_request_error",
              message: "max_tokens: must be greater than or equal to 0",
            },
            request_id: "req_upstream_1",
          }),
          { status: 400, headers: { "content-type": "application/json" } },
        ),
    )

    const response = await post(validBody())

    expect(response.status).toBe(400)
    expect(await response.json()).toEqual({
      type: "error",
      error: {
        type: "invalid_request_error",
        message: "max_tokens: must be greater than or equal to 0",
      },
      request_id: "req_upstream_1",
    })
  })

  it("wraps a local badRequest in the Anthropic envelope", async () => {
    let upstreamCalls = 0
    globalThis.fetch = mock(() => {
      upstreamCalls += 1
      return Promise.resolve(Response.json({}))
    }) as unknown as typeof fetch

    const response = await post(
      JSON.stringify({
        model: "gpt-5.5",
        max_tokens: 64,
        messages: [
          {
            role: "user",
            content: [{ type: "tool_result", tool_use_id: "", content: "x" }],
          },
        ],
      }),
    )

    expect(response.status).toBe(400)
    expect(upstreamCalls).toBe(0)
    expect(await response.json()).toMatchObject({
      type: "error",
      error: { type: "invalid_request_error" },
    })
  })

  it("wraps a local throw in the Anthropic envelope", async () => {
    mockFetchReturning(() => Response.json({}))

    const response = await post("{not json")

    expect(response.status).toBe(500)
    const body = (await response.json()) as {
      type: string
      error: { type: string; message: string }
    }
    expect(body.type).toBe("error")
    expect(body.error.type).toBe("api_error")
    expect(body.error.message).toBeString()
  })

  it("derives the error type from HTTP status when upstream sends non-JSON", async () => {
    mockFetchReturning(
      () =>
        new Response("Unauthorized", {
          status: 401,
          headers: { "content-type": "text/plain" },
        }),
    )

    const response = await post(validBody())

    expect(response.status).toBe(401)
    expect(await response.json()).toEqual({
      type: "error",
      error: {
        type: "authentication_error",
        message: "Authentication failed.",
      },
    })
  })

  it("maps a non-JSON 429 to rate_limit_error", async () => {
    mockFetchReturning(
      () =>
        new Response("slow down", {
          status: 429,
          headers: { "content-type": "text/plain" },
        }),
    )

    const response = await post(validBody())

    expect(response.status).toBe(429)
    expect(await response.json()).toMatchObject({
      type: "error",
      error: { type: "rate_limit_error" },
    })
  })

  it("promotes an OpenAI-shaped upstream error into the Anthropic envelope", async () => {
    mockFetchReturning(
      () =>
        new Response(
          JSON.stringify({
            error: { message: "bad things", code: "invalid_request_body" },
          }),
          { status: 400, headers: { "content-type": "application/json" } },
        ),
    )

    const response = await post(validBody())

    expect(response.status).toBe(400)
    // No top-level type upstream, so one is added and the type derived from
    // the status rather than invented.
    expect(await response.json()).toEqual({
      type: "error",
      error: { type: "invalid_request_error", message: "bad things" },
    })
  })
})

describe("/v1/chat/completions keeps the OpenAI envelope", () => {
  it("does not gain a top-level type", async () => {
    mockFetchReturning(
      () =>
        new Response(
          JSON.stringify({
            error: { message: "bad things", code: "invalid_request_body" },
          }),
          { status: 400, headers: { "content-type": "application/json" } },
        ),
    )

    const response = await server.request("/v1/chat/completions", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        model: "gpt-5.5",
        max_tokens: 64,
        messages: [{ role: "user", content: "hi" }],
      }),
    })

    expect(response.status).toBe(400)
    const body = (await response.json()) as Record<string, unknown>
    expect(body).not.toHaveProperty("type")
    expect(body.error).toMatchObject({ message: "bad things" })
  })
})

import { describe, expect, spyOn, test } from "bun:test"
import consola from "consola"

import { badRequest, forwardError, HTTPError } from "~/lib/error"
import { translateToOpenAI } from "~/routes/messages/non-stream-translation"
import { translateMessageContent } from "~/services/copilot/create-responses"

describe("translateMessageContent multimodal handling", () => {
  test("text part maps to input_text", () => {
    const out = translateMessageContent([{ type: "text", text: "hi" }])
    expect(out).toEqual([{ type: "input_text", text: "hi" }])
  })

  test("image_url part with url maps to input_image", () => {
    const out = translateMessageContent([
      {
        type: "image_url",
        image_url: { url: "https://example.com/x.png", detail: "low" },
      },
    ])
    expect(out).toEqual([
      {
        type: "input_image",
        image_url: "https://example.com/x.png",
        detail: "low",
      },
    ])
  })

  test("image_url part with empty url is dropped with warn", () => {
    const warnSpy = spyOn(consola, "warn").mockImplementation(
      Object.assign(() => {}, { raw: () => {} }),
    )
    try {
      const out = translateMessageContent([
        { type: "image_url", image_url: { url: "" } },
      ])
      expect(out).toEqual([])
      expect(warnSpy).toHaveBeenCalledTimes(1)
    } finally {
      warnSpy.mockRestore()
    }
  })

  test("input_audio part maps to input_audio with data and format", () => {
    const out = translateMessageContent([
      {
        type: "input_audio",
        input_audio: { data: "AAAA", format: "wav" },
      },
    ])
    expect(out).toEqual([
      {
        type: "input_audio",
        input_audio: { data: "AAAA", format: "wav" },
      },
    ])
  })

  test("unknown type is dropped with warn carrying the type label", () => {
    const warnSpy = spyOn(consola, "warn").mockImplementation(
      Object.assign(() => {}, { raw: () => {} }),
    )
    try {
      const out = translateMessageContent([{ type: "mystery_box", text: "" }])
      expect(out).toEqual([])
      expect(warnSpy).toHaveBeenCalledTimes(1)
      const call = warnSpy.mock.calls[0] as
        | [string, Record<string, unknown>]
        | undefined
      expect(call?.[1]).toMatchObject({ unknownType: "mystery_box" })
    } finally {
      warnSpy.mockRestore()
    }
  })
})

describe("empty tool_use_id rejected before upstream call", () => {
  test("throws badRequest with 400 and clean envelope", async () => {
    let thrown: unknown
    try {
      translateToOpenAI({
        model: "claude-test",
        max_tokens: 16,
        messages: [
          {
            role: "user",
            content: [
              {
                type: "tool_result",
                tool_use_id: "",
                content: "hi",
              },
            ],
          },
        ],
      })
    } catch (err) {
      thrown = err
    }

    expect(thrown).toBeInstanceOf(HTTPError)
    const httpErr = thrown as HTTPError
    expect(httpErr.response.status).toBe(400)
    const body = (await httpErr.response.json()) as Record<string, unknown>
    expect(body).toEqual({
      error: {
        type: "invalid_request_error",
        message: "tool_result block is missing tool_use_id",
      },
    })
  })

  test("valid tool_use_id translates without throwing", () => {
    expect(() =>
      translateToOpenAI({
        model: "claude-test",
        max_tokens: 16,
        messages: [
          {
            role: "user",
            content: [
              {
                type: "tool_result",
                tool_use_id: "toolu_abc",
                content: "hi",
              },
            ],
          },
        ],
      }),
    ).not.toThrow()
  })
})

describe("forwardError envelope handling", () => {
  type CapturedJson = { body: unknown; status: number }
  function makeMockContext() {
    const captured: { calls: Array<CapturedJson> } = { calls: [] }
    const c = {
      json(body: unknown, status: number) {
        captured.calls.push({ body, status })
        return new Response(JSON.stringify(body), { status })
      },
    } as unknown as Parameters<typeof forwardError>[0]
    return { c, captured }
  }

  test("upstream {error:{message}} envelope is passed through unchanged", async () => {
    const upstreamBody = {
      error: {
        type: "rate_limit_exceeded",
        message: "too many requests",
        code: "rate_limit",
      },
    }
    const httpErr = new HTTPError(
      "upstream",
      new Response(JSON.stringify(upstreamBody), {
        status: 429,
        headers: { "content-type": "application/json" },
      }),
    )
    const { c, captured } = makeMockContext()
    await forwardError(c, httpErr)
    expect(captured.calls).toHaveLength(1)
    expect(captured.calls[0]).toEqual({ body: upstreamBody, status: 429 })
  })

  test("upstream plain text body is replaced with a safe envelope", async () => {
    const httpErr = new HTTPError(
      "upstream",
      new Response("not json", { status: 502 }),
    )
    const { c, captured } = makeMockContext()
    await forwardError(c, httpErr)
    expect(captured.calls).toHaveLength(1)
    expect(captured.calls[0]).toEqual({
      body: {
        error: {
          type: "upstream_error",
          code: "upstream_error",
          message: "An unexpected upstream error occurred.",
          param: null,
        },
      },
      status: 502,
    })
  })

  test("non-HTTPError errors are wrapped in 500 envelope", async () => {
    const { c, captured } = makeMockContext()
    await forwardError(c, new Error("boom"))
    expect(captured.calls).toHaveLength(1)
    expect(captured.calls[0]).toEqual({
      body: {
        error: {
          type: "server_error",
          code: "internal_error",
          message: "An unexpected error occurred.",
          param: null,
        },
      },
      status: 500,
    })
  })

  test("badRequest synthesises a clean 400 HTTPError", async () => {
    const err = badRequest("missing field")
    expect(err.response.status).toBe(400)
    const body = (await err.response.json()) as Record<string, unknown>
    expect(body).toEqual({
      error: { type: "invalid_request_error", message: "missing field" },
    })
  })
})

import { describe, expect, it, spyOn } from "bun:test"
import consola from "consola"
import { Hono } from "hono"
import { inspect } from "node:util"

import { forwardAnthropicError, forwardError, HTTPError } from "~/lib/error"

const SECRET = "SECRET_SENTINEL_7f3c9a"

async function call(
  protocol: "openai" | "anthropic",
  error: unknown,
): Promise<{ response: Response; logs: string }> {
  const app = new Hono()
  const logs: Array<Array<unknown>> = []
  const log = spyOn(consola, "error")
  const capture = ((...args: Array<unknown>) => {
    logs.push(args)
  }) as typeof consola.error
  log.mockImplementation(capture)
  app.get("/", (c) =>
    protocol === "openai" ?
      forwardError(c, error)
    : forwardAnthropicError(c, error),
  )
  const response = await app.request("/")
  log.mockRestore()
  return { response, logs: inspect(logs, { depth: 8 }) }
}

function httpError(
  status: number,
  body: string,
  headers: Record<string, string> = {},
): HTTPError {
  return new HTTPError("upstream", new Response(body, { status, headers }))
}

describe.each(["openai", "anthropic"] as const)(
  "%s non-stream error normalization",
  (protocol) => {
    it("redacts local Error and object messages from response and logs", async () => {
      for (const error of [
        new Error(`internal ${SECRET}`),
        { message: `object ${SECRET}`, secret: SECRET },
      ]) {
        const { response, logs } = await call(protocol, error)
        const text = await response.text()
        expect(response.status).toBe(500)
        expect(text).not.toContain(SECRET)
        expect(text).toContain("An unexpected error occurred.")
        expect(logs).not.toContain(SECRET)
      }
    })

    it("normalizes arbitrary thrown values to a non-empty message", async () => {
      for (const error of [`string ${SECRET}`, { secret: SECRET }]) {
        const { response, logs } = await call(protocol, error)
        const body = (await response.json()) as Record<string, unknown>
        const outer = body.error as Record<string, unknown>
        const nested =
          outer.error && typeof outer.error === "object" ?
            (outer.error as Record<string, unknown>)
          : outer
        expect(nested.message).toBe("An unexpected error occurred.")
        expect(logs).not.toContain(SECRET)
      }
    })

    it("redacts unrecognized upstream bodies", async () => {
      const { response, logs } = await call(
        protocol,
        httpError(500, `provider ${SECRET}`),
      )
      const text = await response.text()
      expect(response.status).toBe(500)
      expect(text).not.toContain(SECRET)
      expect(text).toContain("An unexpected upstream error occurred.")
      expect(logs).not.toContain(SECRET)
    })

    it("maps a local AbortError to a redacted 499 fallback", async () => {
      const error = new Error("This operation was aborted")
      error.name = "AbortError"
      const { response } = await call(protocol, error)
      const text = await response.text()
      expect(response.status).toBe(499)
      expect(text).toContain("Client closed request.")
      expect(text).not.toContain("This operation was aborted")
    })

    it("preserves safe provider metadata headers", async () => {
      const { response } = await call(
        protocol,
        httpError(429, "Too Many Requests", {
          "x-copilot-service-request-id": "copilot-request",
          "x-github-request-id": "github-request",
          "x-request-id": "generic-request",
          "retry-after": "30",
          "x-ratelimit-limit": "100",
          "x-ratelimit-remaining": "0",
          "x-ratelimit-reset": "999",
          authorization: SECRET,
        }),
      )

      expect(response.status).toBe(429)
      expect(response.headers.get("x-copilot-service-request-id")).toBe(
        "copilot-request",
      )
      expect(response.headers.get("x-github-request-id")).toBe("github-request")
      expect(response.headers.get("x-request-id")).toBe("generic-request")
      expect(response.headers.get("retry-after")).toBe("30")
      expect(response.headers.get("x-ratelimit-limit")).toBe("100")
      expect(response.headers.get("x-ratelimit-remaining")).toBe("0")
      expect(response.headers.get("x-ratelimit-reset")).toBe("999")
      expect(response.headers.get("authorization")).toBeNull()
    })
  },
)

describe("recognized error envelope preservation", () => {
  it("preserves a structured OpenAI error", async () => {
    const envelope = {
      error: {
        type: "invalid_request_error",
        code: "bad_input",
        message: "Invalid field",
        param: "model",
      },
    }
    const { response } = await call(
      "openai",
      httpError(400, JSON.stringify(envelope), {
        "content-type": "application/json",
      }),
    )
    expect(response.status).toBe(400)
    expect(await response.json()).toEqual(envelope)
  })

  it("preserves a native Anthropic error and request_id", async () => {
    const envelope = {
      type: "error",
      error: { type: "authentication_error", message: "Token expired" },
      request_id: "req_123",
    }
    const { response } = await call(
      "anthropic",
      httpError(401, JSON.stringify(envelope), {
        "content-type": "application/json",
      }),
    )
    expect(response.status).toBe(401)
    expect(await response.json()).toEqual(envelope)
  })
})
